  'help.ticketSentDesc': 'Сіздің сұрауыңызды алдық. Командамыз 24 сағат ішінде электронды пошта арқылы жауап береді.',
  'help.close': 'Жабу',
  'help.ticketError': 'Тикетті жіберу сәтсіз болды. Қайтадан кө��іңіз.',
