  'plans.storageWarningUpgrade': 'Chatyy One-ға жаңартыңыз да 200 GB алыңыз!',
  'plans.faqWhatIsPlus': 'Chatyy One деген не?',
  'plans.faqWhatIsPlusAnswer': 'Бұл Chatyy-дің барлық әңгімелеріңізді, суреттеріңізді және бейнелеріңізді қорғайтын премиум жоспары. Chatyy One-мен, егер сіз бірдеңені кездейсоқ жойсаңыз, 30 күнге дейін қалпына келтіре аласыз. Сонымен қатар, сіз 200GB сақтау орны, One AI жеке көмекшісі ретінде аласыз, және 100MB-қа дейін файлдарды жібере аласыз.',
  'plans.faqCancelAnswer': 'Сіздің жоспарыңыз төленген мерзімнің соңына дейін белсенді болады. Одан кейін тегін жоспарға ораласыз. 15GB-тан асатын суреттер мен бейнелеріңіз 30 күн бойы жүктеп алуыңыз үшін сақталады.',
  'plans.faqHowFamily': 'Pro жоспары қалай жұмыс істейді?',
  'plans.faqHowFamilyAnswer': 'Сіз отбасынан 4 адамға дейін қосуға болады. Барлығы 500GB сақтау орнын бөліседі және Chatyy One-ның барлық артықшылықтарын алады. Әр адамда жеке кеңістік бар — ешкім басқалардың файлдарын көрмейді.',
  'plans.faqChangePlanAnswer': 'Иә! Егер Plus-тан Pro-ға жаңартсаңыз, тек пропорционалды айырма алынады. Егер төмендетсеңіз, ағымдағы жоспар мерзімнің соңына дейін сақталады.',
  'plans.faqCardDeclined': 'Менің картам қабылданбады, не істеймін?',
  'plans.faqCardDeclinedAnswer': 'Сізде картаны жаңарту үшін 7 күн бар. Осы мерзім ішінде барлық артықшылықтарыңыз жұмыс істейді. 7 күннен кейін жоспар тегінге оралады.',
